import com.android.tools.lint.detector.api.TextFormat;
import com.android.utils.SdkUtils;
import java.util.EnumSet;

public class IconDetector extends Detector implements BinaryResourceScanner {

    public static final Issue ISSUE = Issue.create(
        "ConvertToWebp",
        "Convert to WebP",
        "The WebP format is typically more compact than PNG and JPEG. As of Android 4.2.1 it supports transparency and lossless conversion as well. Note that there is a quickfix in the IDE which lets you perform conversion.\\n\\nPreviously, launcher icons were required to be in the PNG format but that restriction is no longer there, so lint now flags these.",
        Category.ICONS,
        5,
        Severity.WARNING,
        new Implementation(IconDetector.class, Scope.BINARY_RESOURCE_FILE_SCOPE)
    );

    @Override
    public void checkBinaryResource(@NonNull ResourceContext context, @NonNull BinaryResourceDetector.Type type, @NonNull BinaryResource binaryResource) {
        String name = binaryResource.getName();
        String extension = SdkUtils.getImageFileExtension(name);
        if (extension != null && (extension.equals(EXT_PNG) || extension.equals(EXT_JPG) || extension.equals(EXT_JPEG))) {
            // Only flag images in drawable or mipmap
            ResourceFolderType folderType = ResourceFolderType.getFolderType(context.getResourceFolder());
            if (folderType == DRAWABLE || folderType == MIPMAP) {
                String message = "Convert " + name + " to WebP";
                context.report(ISSUE, Location.create(context.file), message);
            }
        }
    }

    @Override
    @NonNull
    public Speed getBinaryFileScanningSpeed() {
        return Speed.FAST;
    }
}

